style.css:
@-moz-document domain("dnd.su") {
/* Основной анимированный фон с переливом */
    body, html, .wrapper, .main-container, #app {
        background: linear-gradient(135deg, #090d16, #121829, #1b1035, #240046) !important;
        background-size: 400% 400% !important;
        animation: dndGradientAnimation 15s ease infinite !important;
        color: #d8dee9 !important;
    }

    @keyframes dndGradientAnimation {
        0% {
            background-position: 0% 50%;
        }
        50% {
            background-position: 100% 50%;
        }
        100% {
            background-position: 0% 50%;
        }
    }

    /* Затемнение и адаптация основных блоков интерфейса под тему */
    div, section, article, header, footer, aside, nav, .card, .panel {
        background-color: rgba(13, 27, 42, 0.75) !important;
        color: #e2e8f0 !important;
        border-color: #2c3e50 !important;
    }

    /* Поля ввода, таблицы и списки */
    input, select, textarea, table, tr, td, th {
        background-color: rgba(18, 24, 41, 0.85) !important;
        color: #e2e8f0 !important;
        border-color: #3b4252 !important;
    }

    /* Читаемый текст (заголовки, параграфы, ссылки) */
    h1, h2, h3, h4, h5, h6, p, span, li, a {
        color: #eceff4 !important;
    }

    a:hover {
        color: #61afef !important;
        text-shadow: 0 0 8px rgba(97, 175, 239, 0.4);
    }
}
